export function atlasRegion(file,cols,rows,row,col,width,height){
 const frames=FRAME_REGIONS[file];
 if(frames){const [left,top,w,h]=frames[row*cols+col];return {left,top,w,h}}
 const a=ATLAS_CUTS[file];
 if(a)return {left:a.x[col],top:a.y[row],w:a.x[col+1]-a.x[col],h:a.y[row+1]-a.y[row]};
 if(file==='chapter-bosses-v1.png'){const xs=[[0,313,625,951,1261],[0,318,624,943,1261],[0,321,616,945,1261],[0,296,618,943,1261]][row],ys=[0,310,620,932,1247];return {left:xs[col],top:ys[row],w:xs[col+1]-xs[col],h:ys[row+1]-ys[row]}}
 return {left:col*width/cols,top:row*height/rows,w:width/cols,h:height/rows};
}
